SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
START TRANSACTION;

DROP VIEW IF EXISTS `v_sebaran_sekolah_hcid`;
DROP TABLE IF EXISTS `peserta_pelatihan_hcid`;
DROP TABLE IF EXISTS `sekolah_mitra_hcid`;

-- ------------------------------------------------------------------------------
-- 1. TABEL: peserta_pelatihan_hcid (Data Lengkap 509 Peserta Pelatihan)
-- ------------------------------------------------------------------------------
CREATE TABLE `peserta_pelatihan_hcid` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama_kegiatan` VARCHAR(255) NOT NULL COMMENT 'Nama kegiatan / sheet asal',
  `kategori_program` VARCHAR(100) NOT NULL COMMENT 'Smart Urban Farming, GEMS, Kultur Jaringan',
  `tanggal_pelaksanaan` VARCHAR(100) DEFAULT NULL,
  `lokasi_kegiatan` VARCHAR(100) DEFAULT NULL,
  `provinsi` VARCHAR(100) DEFAULT NULL,
  `kabupaten_kota` VARCHAR(100) DEFAULT NULL,
  `nama_peserta` VARCHAR(150) NOT NULL,
  `jenis_kelamin` ENUM('Laki-laki', 'Perempuan') DEFAULT NULL,
  `institusi` VARCHAR(255) DEFAULT NULL COMMENT 'Nama sekolah / institusi',
  `tipe_institusi` VARCHAR(50) DEFAULT 'Sekolah',
  `peran_peserta` VARCHAR(100) DEFAULT NULL,
  `bidang_studi` VARCHAR(255) DEFAULT NULL,
  `pendidikan_terakhir` VARCHAR(255) DEFAULT NULL,
  `no_telepon` VARCHAR(50) DEFAULT NULL,
  `email` VARCHAR(150) DEFAULT NULL,
  `latitude` DECIMAL(10, 7) DEFAULT NULL COMMENT 'Lintang (Y)',
  `longitude` DECIMAL(10, 7) DEFAULT NULL COMMENT 'Bujur (X)',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_hcid_kegiatan` (`nama_kegiatan`),
  INDEX `idx_hcid_program` (`kategori_program`),
  INDEX `idx_hcid_institusi` (`institusi`),
  INDEX `idx_hcid_coords` (`latitude`, `longitude`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

