-- ------------------------------------------------------------------------------
-- 2. VIEW: v_sebaran_sekolah_hcid (Agregasi Sekolah untuk Peta GIS & SEKAR)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_sebaran_sekolah_hcid` AS
SELECT
    `institusi` AS `nama_sekolah`,
    `tipe_institusi`,
    MAX(`provinsi`) AS `provinsi`,
    MAX(`kabupaten_kota`) AS `kabupaten_kota`,
    MAX(`latitude`) AS `latitude`,
    MAX(`longitude`) AS `longitude`,
    COUNT(*) AS `total_peserta`,
    SUM(CASE WHEN `jenis_kelamin` = 'Laki-laki' THEN 1 ELSE 0 END) AS `peserta_laki`,
    SUM(CASE WHEN `jenis_kelamin` = 'Perempuan' THEN 1 ELSE 0 END) AS `peserta_perempuan`,
    GROUP_CONCAT(DISTINCT `kategori_program` SEPARATOR ', ') AS `program_diikuti`,
    GROUP_CONCAT(DISTINCT `nama_kegiatan` SEPARATOR ' | ') AS `daftar_kegiatan`
FROM `peserta_pelatihan_hcid`
WHERE `institusi` IS NOT NULL AND `latitude` IS NOT NULL AND `longitude` IS NOT NULL
GROUP BY `institusi`, `tipe_institusi`;

-- ------------------------------------------------------------------------------
-- 3. TABEL: sekolah_mitra_hcid (Master Data Sekolah untuk SEKAR BIOTROP)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `sekolah_mitra_hcid` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama_sekolah` VARCHAR(255) NOT NULL UNIQUE,
  `provinsi` VARCHAR(100) DEFAULT 'Jawa Barat',
  `kabupaten_kota` VARCHAR(100) DEFAULT 'Kota Bogor',
  `tipe_institusi` VARCHAR(50) DEFAULT 'Sekolah',
  `latitude` DECIMAL(10, 7) NOT NULL,
  `longitude` DECIMAL(10, 7) NOT NULL,
  `total_peserta` INT DEFAULT 1,
  `program_utama` VARCHAR(100) DEFAULT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_sekolah_coords` (`latitude`, `longitude`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sekolah_mitra_hcid` (`nama_sekolah`, `provinsi`, `kabupaten_kota`, `tipe_institusi`, `latitude`, `longitude`, `total_peserta`, `program_utama`)
SELECT `nama_sekolah`, `provinsi`, `kabupaten_kota`, `tipe_institusi`, `latitude`, `longitude`, `total_peserta`, SUBSTRING_INDEX(`program_diikuti`, ',', 1)
FROM `v_sebaran_sekolah_hcid`
ON DUPLICATE KEY UPDATE `total_peserta` = VALUES(`total_peserta`), `program_utama` = VALUES(`program_utama`);

-- ------------------------------------------------------------------------------
-- 4. SINKRONISASI KE TABEL `lokasi` (Titik Sekolah untuk Peta Web GIS Utama)
-- ------------------------------------------------------------------------------
INSERT IGNORE INTO `lokasi` (`nama_lokasi`, `provinsi`, `kabupaten_kota`, `latitude`, `longitude`, `koordinat_manual`)
SELECT `nama_sekolah`, `provinsi`, `kabupaten_kota`, `latitude`, `longitude`, 1
FROM `sekolah_mitra_hcid`;

-- ------------------------------------------------------------------------------
-- 5. SINKRONISASI KE TABEL `kegiatan` & `kegiatan_departemen` (Departemen HCID)
-- ------------------------------------------------------------------------------

INSERT INTO `kegiatan` (
    `kode_kegiatan`, `judul`, `status`, `status_verifikasi`, `location_id`,
    `tanggal_mulai`, `tanggal_selesai`, `penyelenggara`, `skala_kegiatan`,
    `deskripsi`, `jumlah_peserta`, `verified_at`
)
SELECT 
    'KEG-2026-HCID-01', 'Pelatihan Smart Urban Farming Semarang', 'selesai', 'approved', 
    COALESCE((SELECT id FROM lokasi WHERE nama_lokasi LIKE '%Semarang%' LIMIT 1), 1),
    '2026-05-19', '2026-05-22', 'SEAMEO BIOTROP (HCID)', 'Nasional',
    'Pelatihan dan pendampingan sekolah dalam program Pelatihan Smart Urban Farming Semarang oleh departemen HCID SEAMEO BIOTROP.',
    30, NOW()
WHERE NOT EXISTS (SELECT 1 FROM `kegiatan` WHERE `kode_kegiatan` = 'KEG-2026-HCID-01');

INSERT IGNORE INTO `kegiatan_departemen` (`kegiatan_id`, `departemen_kode`)
SELECT id, 'HCID' FROM `kegiatan` WHERE `kode_kegiatan` = 'KEG-2026-HCID-01';


